   400  static int discard_chunk_bytes(spng_ctx *ctx, uint32_t bytes)
   401  {
   402      if(ctx == NULL) return 1;
   403
   404      int ret;
   405
   406      if(ctx->streaming) /* Do small, consecutive reads */
   407      {
   408          while(bytes)
   409          {
   410              uint32_t len = SPNG_READ_SIZE;
   411
   412              if(len > bytes) len = bytes;
   413
   414              ret = read_chunk_bytes(ctx, len);
   415              if(ret) return ret;
   416
   417              bytes -= len;
   418          }
   419      }
   420      else
   421      {
   422          ret = read_chunk_bytes(ctx, bytes);
   423          if(ret) return ret;
   424      }
   425
   426      return 0;
   427  }
