   430  static int read_idat_bytes(spng_ctx *ctx, uint32_t *bytes_read)
   431  {
   432      if(ctx == NULL || bytes_read == NULL) return 1;
   433      if(memcmp(ctx->current_chunk.type, type_idat, 4)) return SPNG_EIDAT_TOO_SHORT;
