   460  static int read_scanline_bytes(spng_ctx *ctx, z_stream *stream, unsigned char *dest, size_t len)
   461  {
   462      if(ctx == NULL || stream == NULL || dest == NULL) return 1;
   463
   464      int ret;
   465      uint32_t bytes_read;
   466
   467      stream->avail_out = len;
   468      stream->next_out = dest;
   469
   470      if(!stream->avail_in)
   471      {
   472          ret = read_idat_bytes(ctx, &bytes_read);
   473          if(ret) return ret;
   474
   475          stream->avail_in = bytes_read;
   476          stream->next_in = ctx->data;
   477      }
   478
   479      do
   480      {
   481          ret = inflate(stream, Z_SYNC_FLUSH);
   482
   483          if(ret != Z_OK)
   484          {/* here we should handle z_stream */
   485              if(ret == Z_STREAM_END) /* zlib reached an end-marker */
   486              {/* we don't have a full scanline or there are more scanlines left */
   487                  if(stream->avail_out != 0) return SPNG_EIDAT_TOO_SHORT;
   488              }
   489              else if(ret != Z_BUF_ERROR) return SPNG_EIDAT_STREAM;
   490          }
   491
   492          /* We don't have scanline_width of data and we ran out of IDAT bytes */
   493          if(stream->avail_out != 0 && stream->avail_in == 0)
   494          {
   495              ret = read_idat_bytes(ctx, &bytes_read);
   496              if(ret) return ret;
   497
   498              stream->avail_in = bytes_read;
   499              stream->next_in = ctx->data;
   500          }
   501
   502      }while(stream->avail_out != 0);
   503
   504      return 0;
   505  }
